'use strict';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const percent=(v,d=1)=>v==null?'—':(v*100).toFixed(d)+'%';
const odds=v=>v==null?'—':(v>0?'+':'')+v;
const implied=v=>v>0?100/(100+v):-v/(100-v);
const markets=f=>f.lines.every(x=>x!=null&&Math.abs(x)>=100)?f.lines.map(x=>implied(x)/f.lines.reduce((s,o)=>s+implied(o),0)):[null,null];
const longshot=f=>f.p!=null&&[f.p,1-f.p].some((p,i)=>f.lines[i]>=200&&p>=.4&&p<=.6&&markets(f)[i]!=null&&p-markets(f)[i]>=.08);
const money=(f,i)=>i?1-f.p:f.p;
const safeUrl=s=>/^https:\/\//.test(s)?esc(s):'#';
const day=s=>new Date(s+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'});
const when=s=>new Date(s).toLocaleString('en-US',{month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit',timeZone:'America/Toronto',timeZoneName:'short'});
const short=s=>s.split(' ').slice(1).join(' ')||s;
let data,ledger,index=0,filter='all',tab='home';
const main=$('#main');
function head(title,description,kicker){return '<div class="pagehead"><div class="eyebrow">'+esc(kicker)+'</div><h1>'+esc(title)+'</h1><div class="meta">'+esc(description)+'</div></div>'}
function sources(){return '<details class="panel stack"><summary>Sources and snapshot times</summary><p class="sources">Forecast saved '+when(data.event.asOf)+'. Historical inputs through '+day(data.statsThrough)+'. '+esc(data.event.oddsLabel)+'. Prices are point-in-time observations.</p><div class="links">'+[...data.event.sources,['Round statistics','https://github.com/Greco1899/scrape_ufc_stats'],['Historical odds · TidyTuesday','https://github.com/rfordatascience/tidytuesday/tree/main/data/2026/2026-07-07']].map(([n,u])=>'<a target="_blank" rel="noreferrer" href="'+safeUrl(u)+'">'+esc(n)+' ↗</a>').join('')+'</div></details>'}
function strip(label,p){return '<div class="barlabels"><span>'+label+'</span><b>'+percent(p)+' / '+percent(p==null?null:1-p)+'</b></div>'+(p==null?'':'<div class="bar"><i style="width:'+p*100+'%"></i></div>')}
function ring(p){const m=p==null?0:Math.max(p,1-p)*100;return '<div class="ring"><svg viewBox="0 0 120 120" aria-hidden="true"><circle cx="60" cy="60" r="55" fill="none" stroke="#5d6857" stroke-width="1" stroke-dasharray="1 4"/><circle cx="60" cy="60" r="47" stroke="#485443" stroke-width="8" fill="none"/><circle cx="60" cy="60" r="47" stroke="#cbfa62" stroke-width="8" fill="none" pathLength="100" stroke-dasharray="'+m+' 100" transform="rotate(-90 60 60)"/></svg><span><b>'+percent(p==null?null:m/100,0)+'</b><small>'+(p==null?'WITHHELD':'MODEL LEAN')+'</small></span></div>'}
function metric(a,label,b){return '<div class="metric"><strong>'+esc(a)+'</strong><span class="mid">'+esc(label)+'</span><strong>'+esc(b)+'</strong></div>'}
function form(s){return s.history.map(h=>'<span title="'+esc(h.date+' vs '+h.opponent)+'" class="form '+(h.win?'':'loss')+'">'+(h.win?'W':'L')+'</span>').join('')||'—'}
function hist(s){return '<div><b>'+esc(s.name)+'</b><div>'+form(s)+'</div>'+s.history.slice().reverse().map(h=>'<p><a target="_blank" rel="noreferrer" href="'+safeUrl(h.url)+'">'+esc(h.opponent)+'</a> · '+esc(h.method)+' · '+esc(h.date)+'</p>').join('')+'</div>'}
function number(v){return v==null?'—':Number(v).toFixed(2)}
function styleRead(a,b){
 if(a.sl==null||b.sl==null)return 'The round archive is incomplete for this pairing. Review the available minutes before comparing rates.';
 const active=a.sl>=b.sl?a:b,grappler=a.td>=b.td?a:b;
 return esc(active.name)+' lands more significant strikes per minute ('+number(active.sl)+'). '+esc(grappler.name)+' averages more completed takedowns per 15 ('+number(grappler.td)+').';
}
function scouting(f) {
 const notes = [f.a,f.b].map(s => [s,data.event.scouting?.[s.name]]).filter(([,note])=>note);
 if(!notes.length) return '';
 const rows = notes.map(([s,note]) => '<div class="journalrow"><b>'+esc(s.name)+'</b><p>'+esc(note.note)+'</p><a href="'+safeUrl(note.source)+'" target="_blank" rel="noreferrer">Read source ↗</a></div>').join('');
 return '<section class="panel stack"><div class="sectionhead"><h2>Scouting notes</h2><span class="tiny">PRE-FIGHT RESEARCH</span></div>'+rows+'<p class="testcopy">Professional and tournament results provide context. CL-1 uses qualifying UFC bouts for its probabilities.</p></section>';
}
function desk(){
 const f=data.card[index],a=f.a,b=f.b,m=markets(f),lead=f.p==null?null:(f.p>=.5?a:b);
 let confidence=f.p==null?winnerRead(f).tier+' · '+winnerRead(f).label+' '+percent(winnerRead(f).chance)+'.':'Model leans '+lead.name+' at '+percent(Math.max(f.p,1-f.p))+'.';
 const board='<div class="board"><article class="hero"><div class="row"><span class="cap">'+(index===0?'Main event':index<data.event.mainCount?'Main card':'Preliminary card')+'</span><span class="tiny">'+esc(f.division)+'</span></div><div class="battle"><div class="fightnames"><strong class="green">'+esc(a.name)+'</strong><small>vs.</small><strong>'+esc(b.name)+'</strong></div>'+ring(f.p??f.limited)+'</div><div class="herofoot"><b>'+esc(confidence)+'</b></div></article><aside class="selection"><div class="sectionhead"><h2>Fight card</h2><span class="tiny">'+data.card.length+' BOUTS</span></div><div class="fightlist" aria-label="Select a matchup">'+data.card.map((v,i)=>'<button class="fbtn '+(i===index?'active':'')+'" aria-pressed="'+(i===index)+'" data-pick="'+i+'"><small>'+esc(v.division)+'</small><b>'+esc(short(v.a.name))+' vs '+esc(short(v.b.name))+'</b></button>').join('')+'</div></aside></div>';
 const tape='<article class="panel"><div class="sectionhead"><h2>Style comparison</h2><span class="tiny">PRIOR BOUTS</span></div><div class="names"><span>'+esc(short(a.name))+'</span><span>'+esc(short(b.name))+'</span></div>'+[['sl','Sig. strikes landed / min'],['sa','Sig. strikes absorbed / min'],['td','Takedowns / 15 min'],['tdd','Takedown defense'],['sub','Sub attempts / 15 min'],['minutes','Measured minutes']].map(([k,l])=>metric(k==='tdd'?percent(a[k],0):number(a[k]),l,k==='tdd'?percent(b[k],0):number(b[k]))).join('')+'<p class="testcopy">'+styleRead(a,b)+'</p></article>';
 const market='<article class="panel"><div class="sectionhead"><h2>Model vs. market</h2><span class="tag grey">CL-1</span></div><div class="names"><span>'+esc(short(a.name))+'</span><span>'+esc(short(b.name))+'</span></div>'+strip('MODEL',f.p)+strip('MARKET · NO VIG',m[0])+metric(odds(f.lines[0]),'American moneyline',odds(f.lines[1]))+metric(f.lines[0]==null?'—':percent(implied(f.lines[0])),'Offered-price break-even',f.lines[1]==null?'—':percent(implied(f.lines[1])))+'<p class="oddsfoot">'+esc(data.event.oddsLabel)+'. The market row removes the bookmaker margin from both sides.</p><p class="testcopy">'+(longshot(f)?'Long-odds review triggered. See the historical results in Model record.':'The long-odds screen does not trigger for this matchup.')+'</p></article>';
 const age='<article class="panel"><div class="sectionhead"><h2>Matchmaking context</h2></div>'+metric(a.age??'—','Age on fight day',b.age??'—')+metric(a.total,'Qualifying UFC bouts',b.total)+metric(Math.round(a.elo),'Opponent-adjusted Elo',Math.round(b.elo))+'<p class="testcopy">'+(f.vet?'Veteran decline rule triggered.': 'Veteran decline rule did not trigger.')+' The rule requires a fighter aged 35+, a five-year age gap, and contrasting three-fight records. Promotional intent is unobserved.</p></article>';
 const subs=f.props?.submission==null?'':'<article class="panel stack"><h2>Submission chances</h2><p class="testcopy">'+esc(f.a.name)+' '+percent(f.props.subA)+' · '+esc(f.b.name)+' '+percent(f.props.subB)+' · either fighter '+percent(f.props.submission)+'.</p></article>';
 return head(data.event.event,day(data.event.date)+'  ·  '+data.event.venue,'Fight desk')+board+subs+scouting(f)+'<div class="grid">'+tape+market+age+'<article class="panel"><div class="sectionhead"><h2>Recent form</h2><span class="tiny">OLDEST → NEWEST</span></div><div class="names"><span>'+esc(short(a.name))+'</span><span>'+form(a)+'</span></div><div class="names"><span>'+esc(short(b.name))+'</span><span>'+form(b)+'</span></div><details><summary>Inspect fight histories</summary><div class="history">'+hist(a)+hist(b)+'</div></details></article></div>'+sources();
}
function scanner(){
 const opts=[['all','All bouts'],['long','Long-odds review'],['vet','Veteran decline'],['thin','Thin history']];
 const rows=data.card.map((f,i)=>({f,i})).filter(({f})=>filter==='all'||(filter==='long'&&longshot(f))||(filter==='vet'&&f.vet)||(filter==='thin'&&f.p==null));
 return head('Market scanner','Compare the underdog’s model probability with the same book’s margin-adjusted price.','Odds research')+'<div class="tabs">'+opts.map(([k,n])=>'<button class="'+(filter===k?'active':'')+'" data-filter="'+k+'">'+n+'</button>').join('')+'</div><div class="panel"><div class="sectionhead"><h2>'+rows.length+' qualifying '+(rows.length===1?'bout':'bouts')+'</h2><span class="tiny">'+esc(data.event.oddsLabel)+'</span></div><div class="scroll"><table><thead><tr><th>Market underdog</th><th>Opponent</th><th>Line</th><th>Market</th><th>Model</th><th>Gap</th></tr></thead><tbody>'+rows.map(({f,i})=>{
 const market=markets(f);if(market[0]==null)return '<tr><td><button class="textbtn" data-open="'+i+'">'+esc(f.a.name+' vs '+f.b.name)+'</button></td><td colspan="5">Paired odds unavailable</td></tr>';
 const ix=market[1]<market[0]?1:0,ff=ix?f.b:f.a,other=ix?f.a:f.b,prob=f.p==null?null:money(f,ix),gap=prob==null?null:(prob-market[ix])*100;
 return '<tr><td><button class="textbtn" data-open="'+i+'">'+esc(ff.name)+'</button></td><td>'+esc(other.name)+'</td><td>'+odds(f.lines[ix])+'</td><td>'+percent(market[ix])+'</td><td>'+percent(prob)+'</td><td>'+(gap==null?'—':(gap>0?'+':'')+gap.toFixed(1)+' pp')+'</td></tr>'}).join('')+'</tbody></table></div>'+(!rows.length?'<p class="testcopy">No matchups meet this rule in the saved card.</p>':'')+'</div><div class="panel stack"><h2>Long-odds rule</h2><p class="testcopy">Underdog priced at +200 or longer, model win chance of 40–60%, and a gap of at least eight percentage points above the no-vig market. Missing histories suppress the forecast. Review the rule’s record before interpreting a signal.</p></div>';
}
function record(){const r=data.report,v=r.vet,l=r.longshot;return head('Model record','CL-1 was fitted on '+r.train.toLocaleString()+' eligible fights through 2022. All results below come from later cards.','Historical validation')+'<div class="stattiles">'+[[r.test.n.toLocaleString(),'Test fights'],[percent(r.test.accuracy),'Model accuracy'],[r.test.brier.toFixed(3),'Brier score']].map(([n,t])=>'<div class="panel"><span class="cap">'+t+'</span><b class="big">'+n+'</b></div>').join('')+'</div><div class="grid"><article class="panel"><h2>Head-to-head with the market</h2><p class="testcopy">'+r.paired.n+' identical bouts with archived prices through '+day(r.pairedEnd)+'. Lower Brier and log loss are better.</p><table><thead><tr><th>Forecast</th><th>Accuracy</th><th>Brier</th><th>Log loss</th></tr></thead><tbody>'+[['CL-1',r.paired],['No-vig market',r.market]].map(([k,x])=>'<tr><td>'+k+'</td><td>'+percent(x.accuracy)+'</td><td>'+x.brier.toFixed(3)+'</td><td>'+x.logloss.toFixed(3)+'</td></tr>').join('')+'</tbody></table></article><article class="panel"><h2>Calibration</h2><p class="testcopy">When the model favored a fighter, how often did that fighter win?</p><table><thead><tr><th>Range</th><th>Forecast</th><th>Won</th><th>Bouts</th></tr></thead><tbody>'+r.cal.map(x=>'<tr><td>'+Math.round(x.lo*100)+'–'+Math.round(x.hi*100)+'%</td><td>'+percent(x.forecast)+'</td><td>'+percent(x.actual)+'</td><td>'+x.n+'</td></tr>').join('')+'</tbody></table></article>'+[[v,'Veteran decline','Younger fighter against a veteran aged 35+ and at least five years older. The veteran lost at least two of three while the younger fighter won at least two of three.'],[l,'Long-odds review','Underdog at +200 or longer with a 40–60% model chance and at least eight points above the no-vig market.']].map(([x,n,desc])=>'<article class="panel"><div class="sectionhead"><h2>'+n+'</h2><span class="tag grey">EXPLORATORY</span></div><b class="big">'+x.wins+' / '+x.n+'</b><p>'+desc+'</p><p class="testcopy">Observed wins <b>'+percent(x.actual)+'</b> · mean market probability <b>'+percent(x.market)+'</b>. Historical prices have incomplete quote timing. These counts do not establish a tradable edge.</p></article>').join('')+'</div><div class="panel stack"><h2>How CL-1 works</h2><p class="testcopy">A frozen logistic regression compares age, experience, recent wins, Elo, striking differential, knockdowns, takedowns, submissions and takedown attempts against opponent defense. Prices are excluded from model inputs. We update fighter histories after each date. The test spans '+day(r.years[0])+' through '+day(r.years[1])+'.</p><p class="testcopy">Coverage includes decisive standard three- and five-round UFC bouts. Ambiguous fighter IDs, draws and no contests are excluded. Rates use complete round sheets. Eligibility requires a known age, at least two qualifying bouts and ten measured minutes per fighter. Earlier opponent divisions and short notice can change how well a career average transfers.</p></div>'+sources()}
function journal(){return head('Forecast journal','Saved pre-fight forecasts and later results are recorded separately.','Audit trail')+'<div class="panel"><div class="sectionhead"><h2>Card snapshots</h2><span class="tiny">CL-1</span></div>'+ledger.map(x=>'<div class="journalrow"><b>'+esc(x.event)+'</b><p>'+when(x.asOf)+' · '+esc(x.count)+' bouts · '+esc(x.issued)+' forecasts</p><a href="'+esc(x.file)+'" download>Download forecast CSV ↓</a>'+((x.result||x.scored)?' · <a href="'+esc(x.result||x.scored)+'" download>'+ (x.result?'Download scored results':'Download partial results') +' ↓</a>':' · Awaiting scoring')+'</div>').join('')+'</div>'}
function render(){
 const views={home:cardHome,results:resultsView,desk,parlay,scanner,record,journal,sources:researchSources};if(!views[tab])tab='home';
 $('nav').querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-pressed',b.dataset.tab===tab)});
 main.innerHTML=views[tab]();$('#stamp').textContent='Forecast snapshot · '+when(data.event.asOf)
}
function goto(k){tab=k;history.replaceState(null,'','#'+k);render()}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!data)return;if(b.dataset.tab)goto(b.dataset.tab);if(b.dataset.filter){filter=b.dataset.filter;render()}if(b.dataset.open!=null){index=Number(b.dataset.open);goto('desk');window.scrollTo(0,0)}if(b.dataset.pick!=null){const list=$('.fightlist');const scroll=[list.scrollLeft,list.scrollTop];index=Number(b.dataset.pick);render();const next=$('.fightlist');next.scrollLeft=scroll[0];next.scrollTop=scroll[1];next.querySelector('.active').focus({preventScroll:true})}});
window.addEventListener('hashchange',()=>{if(data){tab=location.hash.slice(1)||'home';render()}});
async function fetchJSON(path){const response=await fetch(path,{cache:'no-cache'});if(!response.ok)throw Error(response.status);return response.json()}
Promise.all([fetchJSON('data.json'),fetchJSON('journal/index.json'),fetchJSON('results.json'),fetchJSON('evidence.json').catch(()=>null),fetchJSON('references.json').catch(()=>[])]).then(([d,j,archive,e,r])=>{data=d;data.archive=archive;ledger=j;evidence=e;refs=r;if(location.hash==='#sources')getPrivateStates();tab=location.hash.slice(1)||'home';render()}).catch(()=>{main.innerHTML='<div class="panel stack">The fight data could not load. <a href="">Reload the dashboard</a>.</div>'});
